// One event, one letter, one person the band already works with — the
// relationship checks and the contact-window reservation happened upstream,
// inside the approval transaction. This executor either delivers exactly the
// letter that was approved or delivers nothing.
//
// It writes no words of its own. The invitation was composed in CrowdRelay at
// approval time and travels in `draft`; a payload without one is refused
// rather than filled in, because a letter this executor composed would be one
// the band never read — the whole value of the invitation is that it is a
// courtesy between people who know each other.
const e = $json;
if (!e || e.type !== 'crowdrelay.latarnik.invite_requested' || e.version !== 1) {
  throw new Error('latarnik invite refused: unsupported event');
}
const d = e.data ?? {};
const actionId = String(d.action_id || '').trim();
const beaconId = String(d.beacon_id || '').trim();
const draft = d.draft || {};
const subject = String(draft.subject || '').trim();
const body = String(draft.body || '').trim();
if (!actionId || !beaconId) {
  throw new Error('latarnik invite refused: payload incomplete');
}
// The refusal that keeps the promise: no approved words, no send. An action
// queued before CrowdRelay composed letters carries no draft, and writing one
// here on the band's behalf is the exact thing this letter exists to prevent.
if (!subject || !body) {
  throw new Error(
    'latarnik invite refused: no approved letter in the payload — nothing may compose one here'
  );
}
// One recipient, resolved inside the sending lock upstream. The address comes
// from the payload's recipients entry; an empty or multiply-populated set
// means the boundary was bypassed, and that is a stop, not a partial send.
const recipients = Array.isArray(d.recipients) ? d.recipients : [];
if (recipients.length !== 1) {
  throw new Error('latarnik invite refused: expected exactly one recipient');
}
const email = String((recipients[0] && recipients[0].contact_email) || '').trim();
if (!email.includes('@')) {
  throw new Error('latarnik invite refused: recipient without contact_email');
}
return [{ json: {
  event_id: e.id,
  action_id: actionId,
  beacon_id: beaconId,
  recipient_name: String(d.recipient_name || (recipients[0] && recipients[0].name) || ''),
  reason: String(d.reason || ''),
  SendTo: email,
  SendSubject: subject.slice(0, 220),
  SendBody: body,
}}];

const claim = $json;
const intent = $('Validate the approved invitation').first().json;
// A replay of an already-finished action is a no-op, not an error.
if (claim.disposition === 'already_succeeded') return [];
// claimed is the only disposition that may reach the provider; in_flight
// and ambiguous stay claimed upstream and never send twice.
if (claim.disposition !== 'claimed' || !claim.claim_token) {
  throw new Error('Provider execution ' + (claim.disposition || 'unclaimed') + '; fail closed to prevent duplicate external side effects');
}
return [{ json: { ...intent, claim_token: String(claim.claim_token), attempt_number: Number(claim.attempt_number || 1) } }];

const intent = $('Fail-closed claim gate').first().json;
const failed = Boolean($json.error);
const ref = $json.threadId || $json.thread_id || $json.id || null;
return [{ json: {
  action_id: intent.action_id,
  receipt_key: 'latarnik_invite:' + intent.action_id + ':email',
  executor_id: $env.CROWDRELAY_EXECUTOR_ID || 'virya-n8n-primary',
  status: failed ? 'failed' : 'succeeded',
  claim_token: intent.claim_token,
  provider_reference: failed ? null : (ref ? String(ref).slice(0, 240) : null),
  error_kind: failed ? 'gmail_send_failed' : null,
  metadata: {
    channel: 'email',
    event_id: intent.event_id,
    beacon_id: intent.beacon_id,
    recipient_name: intent.recipient_name,
    reason: intent.reason,
  },
  occurred_at: new Date().toISOString(),
}}];
